Aquí están los conceptos extraídos del documento:

```json
{"concepto": "Dominio de diseño operacional (ODD - Operational Design Domain)", "enunciado": "Sistema siendo diseñado permitido para operar en un dominio y condición específicos", "problema": "Definir explícitamente los límites donde un sistema autónomo puede operar responsablemente", "limite": "Difícil de mantener actualizado en la realidad; imposible cubrir todas las condiciones", "patron": "Restringir el espacio de operación permitido a un subconjunto conocido y verificable del dominio completo, explicitando qué queda fuera", "linea": 159}
{"concepto": "Vista de pájaro (BEV - Bird's Eye View)", "enunciado": "Representación espacial unificada donde se fusionan características de múltiples cámaras antes de realizar inferencia, en lugar de que cada cámara juzgue independientemente", "problema": "Evitar errores de consistencia cuando múltiples sensores procesados independientemente dan resultados contradictorios o redundantes", "limite": "Requiere calibración precisa de cámaras y sincronización temporal exacta", "patron": "Fusionar múltiples fuentes heterogéneas en un espacio de representación común antes de tomar decisiones, en lugar de reconciliar decisiones independientes posteriores", "linea": 200}
{"concepto": "Conducción extremo a extremo (End-to-End driving)", "enunciado": "Mapeo directo desde entrada de sensores a trayectoria de salida mediante un modelo aprendido de datos, reemplazando capas intermedias de ingeniería manual explícita", "problema": "Escalar más allá de sistemas basados en reglas que no pueden enumerar completamente los escenarios variables", "limite": "Depende de datos de alta calidad, capacidad computacional significativa y evaluación rigurosa de seguridad", "patron": "Reemplazar una cadena de transformaciones explícitas y codificadas con un modelo que aprende la función global de mapeo desde entrada a salida", "linea": 250}
{"concepto": "Modelo de mundo (World Model)", "enunciado": "Modelo que predice cómo los estados futuros del mundo cambiarán después de una acción ejecutada", "problema": "Permitir que un agente prediga las consecuencias de sus acciones antes de ejecutarlas, habilitando simulación y planificación", "limite": "Las predicciones son imperfectas; el error acumulativo crece con el horizonte temporal", "patron": "Modelar explícitamente la función de transición de estado del sistema para permitir simulación predictiva y evaluación de alternativas sin ejecutarlas", "linea": 307}
{"concepto": "TOPS (Tera Operations Per Second)", "enunciado": "Billones de operaciones de punto flotante por segundo, métrica de capacidad bruta de un procesador", "problema": "Cuantificar la capacidad computacional nominal de un chip", "limite": "Los TOPS nominales no se correlacionan bien con el rendimiento real del modelo; la utilización efectiva es típicamente mucho menor", "patron": "Usar una métrica de capacidad nominal reconociendo que debe complementarse con análisis de eficiencia de utilización real", "linea": 236}
{"concepto": "ASIC (Circuito integrado específico de aplicación - Application-Specific Integrated Circuit)", "enunciado": "Circuito integrado diseñado específicamente para una aplicación o conjunto de algoritmos particulares, codiseñado con la carga de trabajo", "problema": "Lograr eficiencia energética y de rendimiento óptimas para un caso de uso conocido", "limite": "Requiere inversión inicial alta; inflexible para cambios futuros de algoritmos", "patron": "Codiseñar hardware y algoritmo juntos optimizando para un caso de uso específico, a costa de flexibilidad futura", "linea": 237}
{"concepto": "Aprendizaje por refuerzo (Reinforcement Learning - RL)", "enunciado": "Optimizar una política o estrategia mediante un ciclo de retroalimentación donde el sistema recibe recompensas o penalizaciones basadas en sus acciones", "problema": "Permitir que un sistema mejore su comportamiento a través de evaluación iterativa de sus propias acciones", "limite": "Requiere una función de recompensa bien definida; el aprendizaje puede ser inestable", "patron": "Usar retroalimentación de evaluación para ajustar iterativamente el comportamiento del sistema hacia mejores resultados según métricas objetivas", "linea": 470}
{"concepto": "Problema de la cola larga (Long Tail Problem)", "enunciado": "Casos de esquina o eventos que ocurren con baja frecuencia pero que son críticos para seguridad; imposibles de enumerar completamente de antemano", "problema": "Reconocer que los sistemas diseñados por enumeración explícita de casos siempre tendrán brechas impredecibles", "limite": "Inherentemente impredecible cuáles eventos formarán la cola larga", "patron": "Aceptar que no se puede enumerar y codificar todas las variaciones; en su lugar diseñar sistemas que aprendan y se adapten a nuevos casos observados", "linea": 264}
{"concepto": "Fusión temprana vs posterior (Early vs Late Fusion)", "enunciado": "Fusión temprana: fusionar características de múltiples sensores en espacio común antes de inferencia. Fusión posterior: cada sensor hace inferencia independiente, luego se fusionan resultados", "problema": "Reducir inconsistencias y errores cuando múltiples sensores procesan información sobre el mismo mundo", "limite": "Fusión temprana requiere calibración precisa y sincronización temporal de todos los sensores", "patron": "Fusionar información heterogénea a nivel de representación común antes de la toma de decisiones, en lugar de intentar reconciliar decisiones independientes posteriores", "linea": 209}
{"concepto": "Niveles de automatización: L2 vs L3", "enunciado": "L2: persona responsable, sistema asistente. L3: en condiciones específicas, sistema responsable con mecanismo de toma de control disponible", "problema": "Definir claramente quién es responsable legal y operativamente de la seguridad en diferentes contextos de operación", "limite": "L3 requiere definición exhaustiva de ODD y mecanismos de transición; ambigüedad genera riesgo de uso indebido", "patron": "Establecer explícitamente los límites de responsabilidad para evitar ambigüedad donde los usuarios confían pero el sistema no se responsabiliza realmente", "linea": 315}
{"concepto": "Ciclo de datos cerrado (Data Loop Closure)", "enunciado": "Proceso continuo: Flota → Casos → Etiquetado/Entrenamiento → Despliegue → Retroalimentación que forma un bucle", "problema": "Crear un sistema donde el sistema en producción genera automáticamente datos que entrenan versiones mejoradas, que se despliegan a más usuarios", "limite": "Requiere datos de alta calidad, debidamente anonimizados y alineados con objetivos del producto", "patron": "Crear ciclos de retroalimentación cerrados donde sistemas desplegados generan datos que entrenan versiones mejoradas, que se despliegan nuevamente, creando ventajas compuestas", "linea": 374}
